// catalogue/COVERAGE.md: what the catalogue holds, per schema.
import type { Model } from "./model.ts";

export interface CoverageSection {
  title: string;
  models: Model[];
}

export function generateCoverage(sections: CoverageSection[]): string {
  const out: string[] = [
    "# Catalogue coverage",
    "",
    "GENERATED by `tools/catalogue` (`just catalogue-check` regenerates and diffs it). Do not edit.",
    "",
  ];
  for (const s of sections) {
    out.push(`## ${s.title}`, "");
    if (s.models.length === 0) {
      out.push("_No schemas yet._", "");
      continue;
    }
    out.push(
      "| schema | types | entity | symbol | object | child | abstract | faithful | proxy | fields | columns | needs_review |",
      "|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|",
    );
    const flagged: string[] = [];
    const total = Array<number>(11).fill(0);
    for (const m of s.models) {
      const c = (f: (t: Model["types"][number]) => boolean) => m.types.filter(f).length;
      const row = [
        m.types.length,
        c((t) => t.doc.kind === "entity"),
        c((t) => t.doc.kind === "symbol"),
        c((t) => t.doc.kind === "object"),
        c((t) => t.doc.kind === "child"),
        c((t) => t.doc.kind === "abstract"),
        c((t) => t.doc.fidelity === "faithful"),
        c((t) => t.doc.fidelity === "proxy"),
        m.types.reduce((a, t) => a + t.doc.fields.length, 0),
        m.types.reduce((a, t) => a + t.columns.length, 0),
        c((t) => t.doc.needs_review === true),
      ];
      row.forEach((v, i) => (total[i] = (total[i] as number) + v));
      out.push(`| \`${m.schema}\` | ${row.join(" | ")} |`);
      for (const t of m.types) if (t.doc.needs_review) flagged.push(`- \`${t.code}\`${t.doc.notes ? `: ${t.doc.notes.replace(/\s+/g, " ").trim()}` : ""}`);
    }
    if (s.models.length > 1) out.push(`| **total** | ${total.join(" | ")} |`);
    out.push("");
    if (flagged.length > 0) out.push("Types flagged `needs_review`:", "", ...flagged, "");
  }
  return `${out.join("\n").trimEnd()}\n`;
}
